    GRef<f32>(sp + 0x62C) = kd.period2 / F(rec + 0x28);
    GRef<f32>(sp + 0x63C) = ee::fmodf(F(rec + 0x20), F(sp + 0x62C));
    sp = Sp();
    GRef<u32>(sp + 0x580) = W(sp + 0x598);
    GRef<u32>(sp + 0x584) = W(sp + 0x59C);
    GRef<u32>(sp + 0x588) = W(sp + 0x5A0);
    GRef<f32>(sp + 0x648) = fpu::IntToFloat(GRef<s32>(sp + 0x5B0));
    if (kd.scaled) GRef<f32>(sp + 0x620) = 1.25f;
