    // Part 3: debris quads.
    sp = Sp();
    GRef<f32>(sp + 0x62C) = 57600.0f / F(rec + 0x28);
    GRef<f32>(sp + 0x63C) = ee::fmodf(F(rec + 0x20), F(sp + 0x62C));
    sp = Sp();
    if (kd.scaled)
        GRef<f32>(sp + 0x654) = F(sp + 0x660) * F(near ? 0x0040FAB4 : 0x0040FAB8);
    else
        GRef<f32>(sp + 0x654) = F(sp + 0x660) * 128.0f;
