            depth_fade(sp, GRef<s32>(sp + 0x5A4));
            if (GRef<s32>(sp + 0x5A4) <= 0) continue;
            const u32 p = AllocBucketPacket(list, W(sp + 0x5FC), 0xC, 0, 0x5000000C);
            sp = Sp();
            GRef<u32>(sp + 0x570) = p;
