                    const f32 g = fpu::Sub(18.0f, 6.0f / tp), h = fpu::Sub(kd.h4a, kd.h4b / tp);
                    GRef<f32>(sp + 0x654) = F(sp + 0x660) * h * fpu::Add(fpu::Add(t * F(kd.size4_k), F(kd.size4_base)) * g, 1.0f);
