    GRef<u32>(sp + 0x5F0) = W(t + 8);
    GRef<u32>(sp + 0x5F8) = W(t + 0x10);
    GRef<u32>(sp + 0x5F4) = W(t + 0xC);
    const f32 far_z = F(Eff() + 0x62498);
    GRef<s32>(sp + 0x578) = fpu::FloatToInt(far_z);
    GRef<u32>(0x00410BAC) = sp;
    GRef<s32>(sp + 0x57C) = fpu::FloatToInt(fpu::Sub(F(Eff() + 0x62494), far_z) / F(0x0040ED18));
