    GRef<u32>(sp + 0x5F0) = W(t + 8);
    GRef<u32>(sp + 0x5F4) = W(t + 0xC);
    GRef<u32>(sp + 0x5F8) = W(t + 0x10);
    const f32 range = fpu::Sub(F(Eff() + 0x62494), far_z) / F(0x0040ED2C);
    GRef<s32>(sp + 0x578) = fpu::FloatToInt(far_z);
    const u32 c = W(0x002B8560);
    GRef<u32>(0x00410BAC) = sp;
    GRef<s32>(sp + 0x57C) = fpu::FloatToInt(range);
    GRef<u32>(sp + 0x580) = GRef<u8>(c + 0x38);
    GRef<u32>(sp + 0x584) = GRef<u8>(c + 0x39);
    GRef<u32>(sp + 0x588) = GRef<u8>(c + 0x3A);
    GRef<f32>(sp + 0x648) = fpu::UnsignedToFloat(GRef<u8>(c + 0x3B));
    GRef<u32>(sp + 0x6B0) = W(t + 0x18C);
    GRef<u32>(sp + 0x6B4) = W(t + 0x190);
    GRef<u32>(sp + 0x6B8) = W(t + 0x194);
    GRef<f32>(sp + 0x4AC) = 1.0f;
    GRef<u32>(sp + 0x6BC) = W(t + 0x198);
    GRef<f32>(sp + 0x624) = fpu::Sub(F(cam + 0x168), F(0x0040ED30)) / F(0x0040ED34) * F(0x0040ED38);
