    GRef<f32>(sp + 0x660) = F(cs + static_cast<u32>(GRef<s32>(sp + 0x604)) * 8) * F(0x0040ED58);
    CopyQ(sp + 0x520, rec + 0x10);
    sp = Sp();
    if (GRef<s32>(sp + 0x61C) == 1)
        GRef<f32>(sp + 0x520) = fpu::Add(F(sp + 0x520), F(0x0040ED5C));
    else if (GRef<s32>(sp + 0x61C) == 0xF)
        GRef<f32>(sp + 0x520) = fpu::Add(F(sp + 0x520), F(0x0040ED60));
    sceVu0UnitMatrix(sp + 0x2C0);  // inline vmr32 unit matrix in the original
