            GRef<f32>(sp + 0x688) = fpu::Add(u0, 0.0625f);
            const s32 rr = ((i << 3) - i) + ((band << 1) + band);
            SpriteUvsByCase(sp, u0, rr - (((rr < 0 ? rr + 3 : rr) >> 2) << 2), kUv);
