// EE: 0x001D9E50
// Frustum block `out` for the trail draws: half width / height / distance (+0x50..+0x58), near
// (+0x5C, distance / 2 when 0) and far (+0x60, C 0x0040FD94 when 0), the edge slopes (h / d,
// -w / d, -h / d, w / d at +0x40..+0x4C) and the four side-plane normals +0x00..+0x30: the
// normalised cross products of consecutive corners (w, h, d), (-w, h, d), (-w, -h, d), (w, -h, d).
void func_001D9E50(u32 out, f32 hw, f32 hh, f32 dist, f32 near_z, f32 far_z) {
    GRef<f32>(out + 0x50) = hw;
    GRef<f32>(out + 0x54) = hh;
    GRef<f32>(out + 0x58) = dist;
    GRef<f32>(out + 0x5C) = near_z == 0.0f ? dist * 0.5f : near_z;
    GRef<f32>(out + 0x60) = far_z == 0.0f ? F(0x0040FD94) : far_z;
    guest::GuestFrame fr(0x40);
    const u32 c = fr.Address(0);
    GRef<f32>(c) = hw;
    GRef<f32>(c + 4) = hh;
    GRef<f32>(c + 8) = dist;
    GRef<f32>(c + 0xC) = 1.0f;
    GRef<f32>(out + 0x40) = hh / dist;
    GRef<f32>(out + 0x44) = -hw / dist;
    GRef<f32>(out + 0x48) = -hh / dist;
    GRef<f32>(out + 0x4C) = hw / dist;
    CopyQ(c + 0x10, c);
    GRef<f32>(c + 0x10) = -hw;
    CopyQ(c + 0x20, c + 0x10);
    GRef<f32>(c + 0x24) = -hh;
    CopyQ(c + 0x30, c);
    GRef<f32>(c + 0x34) = -hh;
    for (u32 i = 0; i < 4; ++i) {
        const u32 n = out + i * 0x10;
        sceVu0OuterProduct(n, c + i * 0x10, c + ((i + 1) & 3) * 0x10);
        NormRsqrt(n, n);
    }
}

