// Guard band of the screen from the main context's display size (+0x70 width, +0x72 height):
// centre 0x800 +- half size in 12.4 fixed point, widened by 0x2000.
void ScreenGuardBand(u32 sp) {
    const u32 ctx = W(0x004104A8);
    const u32 w = GRef<u16>(ctx + 0x70), h = GRef<u16>(ctx + 0x72);
    GRef<u32>(sp + 0x5F8) = ((0x800u - (h >> 1)) << 4) - 0x2000u;
    GRef<u32>(sp + 0x5EC) = (((w >> 1) + 0x800u) << 4) + 0x2000u;
    GRef<u32>(sp + 0x5F0) = ((0x800u - (w >> 1)) << 4) - 0x2000u;
    GRef<u32>(sp + 0x5F4) = (((h >> 1) + 0x800u) << 4) + 0x2000u;
}

