            sp = Sp();
            const u32 v = 0x002B91C0 + (static_cast<u32>(GRef<s32>(sp + 0x604) + i * GRef<s16>(rec + 0x28)) & 0x3F) * 16;
            const f32 r = quarter ? F(sp + 0x66C) * 0.25f : F(sp + 0x66C);
