            GRef<f32>(sp + 0x4A4) = quarter ? fpu::Sub(F(rec + 4), r * F(v + 4)) : fpu::Add(F(rec + 4), r * F(v + 4));
            GRef<f32>(sp + 0x4A8) = fpu::Add(F(rec + 8), r * F(v + 8));
            ProjectI4(sp + 0x410, vm, sp + 0x4A0, true);
            GRef<u32>(sp + 0x5FC) = DepthBucket(GRef<s32>(sp + 0x41C));
            const s32 pw = GRef<s32>(sp + 0x41C);
            if (pw < 0x10 || !InGuardBand(sp, 0x410)) return false;
