        GRef<s32>(sp + 0x580) = GRef<u8>(c + 0x48) >> 1;
        GRef<s32>(sp + 0x584) = GRef<u8>(c + 0x49) >> 1;
        GRef<s32>(sp + 0x588) = GRef<u8>(c + 0x4A) >> 1;
