        GRef<u32>(sp + 0x588) = GRef<u8>(c + 0x56);
        GRef<f32>(sp + 0x648) = fpu::IntToFloat(GRef<u8>(c + 0x57));
        const f32 k = F(c + 0x5C);
        GRef<f32>(sp + 0x654) = k;
