        if (!(gw < 0x259)) GRef<s32>(sp + 0x61C) = (gw - 0x258) / 0x320 + 1;
        if (!(GRef<s32>(sp + 0x61C) < 0x11)) GRef<s32>(sp + 0x61C) = 0x10;
