    if (!(GRef<s32>(sp + 0x46C) < 0x5A1)) GRef<s32>(sp + 0x604) = 2;
    if (!(GRef<s32>(sp + 0x46C) < 0x781)) GRef<s32>(sp + 0x604) = 1;
    if (!(GRef<s32>(sp + 0x46C) < 0x1900)) return;
