// EE: 0x00197CF0
// Mission 0xD unit effect (record {pos, +0xC age, +0x1C life, +0x24 phase, +0x28 group}): alpha
// ramps in over a quarter of the life, holds to C 0x0040F27C of it and fades by the table
// 0x002B8630 [phase & 0xF]. The record (w biased by +0x624, nothing behind the near limit) takes
// the group's depth bucket (0x002B89E4 [group]); 3 / 2 / 1 puffs by distance (alpha scaled up to
// w 0x3200, then halved per 128 beyond). Each puff of the vector table [i x 7 + phase] drifts by
// age (x C 0x0040F288 x C 0x0040F28C) and rises, fades with depth and with distance (the 2nd beyond
// w 0x1900, the 3rd always), grows with age (table 0x002B8630) and is drawn as a 6-vertex fan with
// fixed UVs, the centre at alpha +0x5A8, the corner colours rotated by the puff index.
// fpucheck: verified 18
void func_00197CF0(u32 rec, u32 cam, u32 list) {
    u32 sp = Sp();
    const u32 vm = cam + 0xE0;
    const u32 T3 = 0x002B8630;
    {
        const f32 age = F(rec + 0xC), life = F(rec + 0x1C);
        GRef<f32>(sp + 0x638) = age;
        const f32 rise = life * 0.25f;
        if (age < rise) {
            GRef<s32>(sp + 0x5A4) = fpu::FloatToInt(age * F(sp + 0x648) / rise);
        } else if (age < life * F(0x0040F27C)) {
            GRef<s32>(sp + 0x5A4) = fpu::FloatToInt(F(sp + 0x648));
        } else {
            const f32 tv = F(T3 + (W(rec + 0x24) & 0xFu) * 4);
            const f32 d = life * fpu::Add(tv * F(0x0040F280), F(0x0040F284));
            const s32 v = fpu::FloatToInt(F(sp + 0x648) * fpu::Sub(1.0f, fpu::Sub(age, life * F(0x0040F27C)) / d));
            GRef<s32>(sp + 0x5A4) = v;
            if (v < 2) return;
        }
    }
    CopyQ(sp + 0x4A0, rec);
    sp = Sp();
    GRef<f32>(sp + 0x4AC) = 1.0f;
    ProjectI4(sp + 0x410, vm, sp + 0x4A0, true);
    {
        const s32 w0 = GRef<s32>(sp + 0x41C);
        const s32 w = w0 - fpu::FloatToInt(fpu::IntToFloat(w0) * F(sp + 0x624));
        GRef<s32>(sp + 0x41C) = w;
        if (w < 0x10) return;
        const u32 slot = 0x002B89B0 + 0x34 + W(rec + 0x28) * 4;
        if (GRef<s32>(slot) != -1) {
            GRef<u32>(sp + 0x5FC) = W(slot);
        } else {
            GRef<u32>(sp + 0x5FC) = DepthBucket(w);
            GRef<u32>(slot) = W(sp + 0x5FC);
        }
    }
    {
        const s32 w = GRef<s32>(sp + 0x41C);
        GRef<s32>(sp + 0x604) = 3;
        if (static_cast<u32>(w - 0x1901) < 0x1900u) {
            GRef<s32>(sp + 0x604) = 2;
            GRef<s32>(sp + 0x5A4) = GRef<s32>(sp + 0x5A4) * w / 0x1900;
        }
        const s32 w2 = GRef<s32>(sp + 0x41C);
        if (!(w2 < 0x3201)) {
            const s32 d = w2 - 0x3200;
            GRef<s32>(sp + 0x604) = 1;
            GRef<s32>(sp + 0x5A4) = (GRef<s32>(sp + 0x5A4) << 1) - d / 128;
        }
    }
    if (GRef<s32>(sp + 0x5A4) <= 0) return;
    EffectTexHeader(list, GRef<s32>(sp + 0x5FC), 0x44);
    for (s32 s0 = 0; s0 < GRef<s32>(Sp() + 0x604); ++s0) {
        sp = Sp();
        GRef<f32>(sp + 0x65C) = fpu::IntToFloat(s0);
        CopyQ(sp + 0x560, 0x002B91C0 + ((static_cast<u32>(s0) * 7 + W(rec + 0x24)) & 0x7F) * 16);
        sp = Sp();
        if (F(sp + 0x564) < 0.0f) GRef<f32>(sp + 0x564) = -F(sp + 0x564);
        {
            const f32 s = F(sp + 0x660), age = F(sp + 0x638);
            const f32 k = s * F(0x0040F288), c = F(0x0040F28C);
            const f32 tz = fpu::Add(k * F(sp + 0x568) * age, 16.0f) * c;
            const f32 tx = fpu::Add(k * F(sp + 0x560) * age, 16.0f) * c;
            GRef<f32>(sp + 0x4A0) = fpu::Add(fpu::Add(F(rec), F(sp + 0x560) * 48.0f), tz);
            GRef<f32>(sp + 0x4A8) = fpu::Add(fpu::Add(F(rec + 8), F(sp + 0x568) * 48.0f), tx);
            const f32 up = fpu::Add(F(sp + 0x564), 0.75f) * age * s;
            GRef<f32>(sp + 0x4A4) = fpu::Sub(fpu::Add(F(rec + 4), F(sp + 0x564) * 48.0f), up);
        }
        ProjectI4(sp + 0x410, vm, sp + 0x4A0, true);
        if (GRef<s32>(sp + 0x41C) < 0x10) return;
        if (!InGuardBand(sp, 0x410)) continue;
        {
            const s32 w0 = GRef<s32>(sp + 0x41C);
            const s32 a = GRef<s32>(sp + 0x5A4);
            GRef<s32>(sp + 0x42C) = w0;
            GRef<s32>(sp + 0x5A8) = a;
            const s32 w = w0 - fpu::FloatToInt(fpu::IntToFloat(w0) * F(sp + 0x624));
            GRef<s32>(sp + 0x41C) = w;
            if (w < 0x100) {
                GRef<s32>(sp + 0x5A8) = a - (0x100 - w) / 1;
            } else if (GRef<s32>(sp + 0x578) < w) {
                GRef<s32>(sp + 0x5A8) = a - a * (w - GRef<s32>(sp + 0x578)) / GRef<s32>(sp + 0x57C);
            }
        }
        if (GRef<s32>(sp + 0x5A8) < 2) continue;
        {
            const s32 a = GRef<s32>(sp + 0x5A8);
            const s32 w = GRef<s32>(sp + 0x41C);
            if (s0 == 1) {
                if (!(w < 0x1901)) GRef<s32>(sp + 0x5A8) = a - a * (w - 0x1900) / 0x1900;
            } else if (s0 == 2) {
                GRef<s32>(sp + 0x5A8) = a - a * w / 0x1900;
            }
        }
        if (GRef<s32>(sp + 0x5A8) < 2) continue;
        {
            const f32 life = F(rec + 0x1C), age = F(sp + 0x638);
            const f32 hl = life * 0.5f;
            const f32 tv = F(T3 + ((W(rec + 0x24) + 5u) * static_cast<u32>(s0) & 0xFu) * 4);
            if (age < hl)
                GRef<f32>(sp + 0x654) = fpu::Add(age * 0.75f * fpu::Add(tv * 60.0f, age * 120.0f / life) / hl, 24.0f);
            else
                GRef<f32>(sp + 0x654) = fpu::Add(fpu::Add(fpu::Add(tv * 60.0f, 60.0f), fpu::Sub(age, hl) * F(0x0040F290) * 120.0f / life) * 0.75f, 24.0f);
        }
        {
            const u32 par = static_cast<u32>(s0) & 1;
            const f32 size = F(sp + 0x654);
            const f32 fw = fpu::IntToFloat(GRef<s32>(sp + 0x42C));
            GRef<s32>(sp + 0x60C) = fpu::FloatToInt(F(sp + 0x6B0 + par * 8) * size / fw);
            GRef<s32>(sp + 0x610) = fpu::FloatToInt(F(sp + 0x6B4 + par * 8) * size / fw);
        }
        const u32 p = AllocBucketPacket(list, GRef<s32>(sp + 0x5FC), 0x14, 0, 0x50000014);
        sp = Sp();
        GRef<u32>(sp + 0x570) = p;
        Emit(0x13, 0x10000000, 0xE, 0);
        Emit(0x5D, kKeep, 0, 0);
        GRef<s32>(sp + 0x41C) = (GRef<s32>(sp + 0x418) * 5) / 4;
        static const u32 kRot[4] = {0, 1, 3, 2};
        static const u32 kEdge[4][4] = {{0x580, 0x58C, 0x598, 0x58C},
                                        {0x598, 0x58C, 0x580, 0x58C},
                                        {0x58C, 0x580, 0x58C, 0x598},
                                        {0x58C, 0x598, 0x58C, 0x580}};
        const u32* e = kEdge[kRot[static_cast<u32>(s0) & 3]];
        const u32 one = 0x3F800000;
        const s32 cx = GRef<s32>(sp + 0x60C), cy = GRef<s32>(sp + 0x610);
        Emit(0x3E000000, 0x3EC00000, 2, 0);
        Emit(SpRgba(sp, 0x58C, W(sp + 0x5A8)), one, 1, 0);
        EmitXyzOff(sp, 0, 0);
        Emit(0, 0x3E800000, 2, 0);
        Emit(SpRgba(sp, e[0], 0), one, 1, 0);
        EmitXyzOff(sp, -cx, -cy);
        Emit(0x3E800000, 0x3E800000, 2, 0);
        Emit(SpRgba(sp, e[1], 0), one, 1, 0);
        EmitXyzOff(sp, cy, -cx);
        Emit(0x3E800000, 0x3F000000, 2, 0);
        Emit(SpRgba(sp, e[2], 0), one, 1, 0);
        EmitXyzOff(sp, cx, cy);
        Emit(0, 0x3F000000, 2, 0);
        Emit(SpRgba(sp, e[3], 0), one, 1, 0);
        EmitXyzOff(sp, -cy, cx);
        Emit(0, 0x3E800000, 2, 0);
        Emit(SpRgba(sp, e[0], 0), one, 1, 0);
        EmitXyzOff(sp, -cx, -cy);
    }
}

