// EE: 0x0017F760
// Player gun effect pool (+0x5EAB0) draw set-up: far depth and fade range (/ C 0x0040EC58), the
// horizontal guard band (+-0x2000) at +0x5E4 / +0x5E8 and the point 16 ahead of the camera (its
// position plus (0, 0, 16) rotated by the camera angles) at +0x4F0.
// fpucheck: verified 4
void func_0017F760(u32 cam, u32 /*list*/) {
    const u32 sp = 0x70000000;
    const f32 far_z = F(Eff() + 0x62498);
    GRef<s32>(sp + 0x578) = fpu::FloatToInt(far_z);
    const f32 range = fpu::Sub(F(Eff() + 0x62494), far_z) / F(0x0040EC58);
    guest::GuestFrame fr(0x80);
    const u32 m = fr.Address(0), r = fr.Address(0x40);
    GRef<f32>(m + 8) = 16.0f;
    {
        const u32 w = GRef<u16>(W(0x004104A8) + 0x70);
        GRef<s32>(sp + 0x57C) = fpu::FloatToInt(range);
        GRef<u32>(m) = 0;
        GRef<u32>(sp + 0x5E8) = ((0x800u - (w >> 1)) << 4) - 0x2000u;
        GRef<u32>(sp + 0x5E4) = (((w >> 1) + 0x800u) << 4) + 0x2000u;
    }
    GRef<u32>(0x00410BAC) = sp;
    GRef<u32>(m + 4) = 0;
    func_00102D28(r, m, cam + 0x10);
    const u32 s = Sp();
    GRef<f32>(s + 0x4F0) = fpu::Add(F(cam), F(r));
    GRef<f32>(s + 0x4F4) = fpu::Add(F(cam + 4), F(r + 4));
    GRef<f32>(s + 0x4FC) = 1.0f;
    GRef<f32>(s + 0x4F8) = fpu::Add(F(cam + 8), F(r + 8));
}

// EE: 0x0017F870
// Player gun effect (record {pos, +0x10 rotation, +0x20 age, +0x24 barrel 1..4, +0x26 effect
