        sp = Sp();
        if (F(sp + 0x564) < 0.0f) GRef<f32>(sp + 0x564) = -F(sp + 0x564);
        {
            const f32 t0 = F(sp + 0x63C), k = F(sp + 0x630), size = F(sp + 0x660);
            f32 x, z;
            if (Game(0x27) == 4) {
                x = fpu::Add(F(sp + 0x560), F(sp + 0x4E0) * k22 * t0);
                z = fpu::Add(F(sp + 0x568), F(sp + 0x4E8) * k22 * t0);
            } else {
                x = fpu::Add(F(sp + 0x560), fpu::Add(F(sp + 0x4E0), F(sp + 0x4E0)) * t0);
                z = fpu::Add(F(sp + 0x568), fpu::Add(F(sp + 0x4E8), F(sp + 0x4E8)) * t0);
            }
            GRef<f32>(sp + 0x560) = x;
            GRef<f32>(sp + 0x568) = z;
            f32 g, lift;
            if (Game(0x27) == 4) {
                g = fpu::Add(t0 * k21 * k, odd ? 8.0f : 16.0f);
                lift = size * (odd ? k24 : 0.25f) * fpu::Add(F(sp + 0x564), 1.0f) * t0 * k;
            } else {
                g = fpu::Add(t0 * (odd ? k23 : F(0x0040FC90)) * k, odd ? 8.0f : 16.0f);
                lift = size * k23 * fpu::Add(F(sp + 0x564), 1.0f) * t0 * k;
            }
            GRef<f32>(sp + 0x4A8) = fpu::Add(F(sp + 0x4B8), size * (g * z));
            GRef<f32>(sp + 0x4A0) = fpu::Add(F(sp + 0x4B0), size * (g * x));
            GRef<f32>(sp + 0x4A4) = fpu::Sub(F(sp + 0x4B4), lift);
        }
        ProjectI4(sp + 0x410, vm, sp + 0x4A0, true);
        if (GRef<s32>(sp + 0x41C) < 0x10 || !InGuardBand(sp, 0x410)) continue;
        {
            const f32 t0 = F(sp + 0x63C), k = F(sp + 0x630), size = F(sp + 0x660);
            if (!odd) {
                const f32 g = fpu::Add(F(vec(i) + 4) * k23, 1.0f);
                const f32 h = fpu::Add(fpu::Add(F(vec(i + ph2)) * F(0x0040FC94), F(0x0040FC98)) * t0 * k, 10.0f);
                GRef<f32>(sp + 0x654) = size * g * h;
            } else if (Game(0x27) == 4) {
                const f32 g = fpu::Add(F(vec(i) + 4) * k21, F(0x0040FC88));
                const f32 h = fpu::Add(t0 * k21 * k, F(0x0040FC8C));
                GRef<f32>(sp + 0x654) = size * g * h;
            } else {
                const f32 g = fpu::Add(F(vec(i) + 4) * k24, F(0x0040FC9C));
                const f32 h = fpu::Add(t0 * 0.25f * k, F(0x0040FCA0));
                GRef<f32>(sp + 0x654) = size * g * h;
            }
        }
        size_and_fade(sp, sp + 0x6D8 + static_cast<u32>(i & 1) * 8);
        if (GRef<s32>(sp + 0x5A4) < 5) continue;
