// Body of 0x001D8A98 / 0x001D8E88 (UV sets `uvs`): a sprite of half size `size` x camera scale
// (+0x180 / +0x184) around screen point `s` (x, y, z words) as PRIM 0x156 sprites in strips of up
// to 0x400 (64 pixels; the first strip ends on a 64-pixel boundary). The strip count is
// ((right + 0x3FF) >> 4) - (left >> 4), as the original (strips past the width have zero width).
// UVs: set (flags & 7) (flags bit 1 cleared first) offset by (u, v) << 4 + 8: u0 +0 / u1 +0xC,
// v0 +2 / v1 +0xE. Flags bit 0: the texture runs along y (v interpolated along x), else u along x.
void SpriteStripRow(u32 gb, u32 s, u32 cam, u32 rgba, s16 u, s16 v, u32 flags, f32 size, u32 uv_table) {
    const s32 hx = fpu::FloatToInt(size * F(cam + 0x180));
    const s32 hy = fpu::FloatToInt(size * F(cam + 0x184));
    const s32 x = GRef<s32>(s), y = GRef<s32>(s + 4);
    s32 width = hx * 2;
    const s32 left = x - hx;
    s32 n = ((x + hx + 0x3FF) >> 4) - (left >> 4);
    const s32 bottom = y + hy;
    const s32 top = y - hy;
    if (n <= 0) return;
    flags &= 0xFFFFFFFDu;
    const u32 uvs = uv_table + (flags & 7) * 16;
    const u32 ub = (static_cast<u32>(u) << 20) >> 16;
    const u32 vb = (static_cast<u32>(v) << 20) >> 16;
    const s32 u0 = static_cast<s16>(ub + GRef<u16>(uvs) + 8);
    const s32 v0 = static_cast<s16>(vb + GRef<u16>(uvs + 2) + 8);
    const s32 u1 = static_cast<s16>(ub + GRef<u16>(uvs + 0xC) + 8);
    const s32 v1 = static_cast<s16>(vb + GRef<u16>(uvs + 0xE) + 8);
    s32 step = 0x400 - (left & 0x3FF);
    GifOpenAd(gb);
    GifAd(gb, 0x156, 0);
    const u32 t = GifBeginTag(gb, static_cast<u64>(n) | 0x5400000000008000ull,
                              ((static_cast<u32>(n * 0x28) + 0xF) >> 4) + 1);
    GRef<u64>(t + 8) = 0x53531;
    u32 q = t + 0x10;
    const s32 z = GRef<s32>(s + 8);
    s32 done = 0;
    s32 xa = left;
    if ((flags & 1) != 0) {
        const f32 k = fpu::Div(fpu::IntToFloat(v1 - v0), fpu::IntToFloat(width));
        s32 va = v0;
        for (; n > 0; --n, q += 0x28) {
            if (width < step) step = width;
            GRef<u32>(q + 8) = (static_cast<u32>(u0) & 0xFFFF) | static_cast<u32>(va) << 16;
            GRef<u32>(q) = rgba;
            done += step;
            GRef<u64>(q + 0x10) = GifXyz(xa, top, z);
            xa = left + done;
            GRef<u32>(q + 4) = 0;
            width -= step;
            step = 0x400;
            va = v0 + fpu::FloatToInt(k * fpu::IntToFloat(done));
            GRef<u32>(q + 0x18) = (static_cast<u32>(u1) & 0xFFFF) | static_cast<u32>(va) << 16;
            GRef<u64>(q + 0x20) = GifXyz(xa, bottom, GRef<s32>(s + 8));
        }
    } else {
        const f32 k = fpu::Div(fpu::IntToFloat(u1 - u0), fpu::IntToFloat(width));
        s32 ua = u0;
        for (; n > 0; --n, q += 0x28) {
            if (width < step) step = width;
            done += step;
            GRef<u32>(q + 8) = (static_cast<u32>(ua) & 0xFFFF) | (static_cast<u32>(v0) & 0xFFFF) << 16;
            GRef<u32>(q) = rgba;
            GRef<u64>(q + 0x10) = GifXyz(xa, top, GRef<s32>(s + 8));
            xa = left + done;
            GRef<u32>(q + 4) = 0;
            width -= step;
            ua = u0 + fpu::FloatToInt(k * fpu::IntToFloat(done));
            step = 0x400;
            GRef<u32>(q + 0x18) = (static_cast<u32>(ua) & 0xFFFF) | (static_cast<u32>(v1) & 0xFFFF) << 16;
            GRef<u64>(q + 0x20) = GifXyz(xa, bottom, GRef<s32>(s + 8));
        }
    }
}

// Body of 0x001D9278 / 0x001D95A8 (UV sets `uvs`): a fan of 6 vertices (REGLIST RGBAQ, UV, XYZ2;
// PRIM 0x15D): the centre at screen point `s` with colour `rgba` and UV (u + 0x100, v + 0x100), then
// the corners (x -+ a, y -+ b) / (x -+ c, y -+ d) with alpha 0 and the UVs of set `set`, closing on
// the first corner. The corner offsets a, b, c, d are four halfwords read from the bottom of the
// function's own stack frame, which it never writes (the original reads whatever is there; the port
// reads its guest stack frame the same way).
void FanQuad(u32 gb, u32 s, u32 rgba, s16 u, s16 v, u32 set, u32 uv_table) {
    guest::GuestFrame frame(0x10);
    const u32 junk = frame.Address();
    const u32 uvs = uv_table + (set & 7) * 16;
    GifOpenAd(gb);
    GifAd(gb, 0x15D, 0);
    const u32 vb = static_cast<u16>(v), ub = static_cast<u16>(u);
    const u32 ta = vb + GRef<u16>(uvs + 2) + 8, tb = vb + GRef<u16>(uvs + 6) + 8;
    const u32 tc = vb + GRef<u16>(uvs + 0xE) + 8, td = vb + GRef<u16>(uvs + 0xA) + 8;
    const u32 sa = ub + GRef<u16>(uvs) + 8, sb = ub + GRef<u16>(uvs + 4) + 8;
    const u32 sc = ub + GRef<u16>(uvs + 0xC) + 8, sd = ub + GRef<u16>(uvs + 8) + 8;
    const u32 t = W(gb) + W(gb + 8) * 16;
    GRef<u32>(gb + 4) = W(gb + 4) + 10;
    GRef<u32>(gb + 8) = W(gb + 8) + 10;
    GRef<u32>(gb + 0x14) = 0;
    GRef<u64>(gb + 0x18) = 0x3400000000008006ull;
    GRef<u64>(t + 8) = 0x531;
    const u32 corner = rgba & 0x00FFFFFFu;
    const u32 uv_a = (sa & 0xFFFF) | ta << 16;
    GRef<u32>(t + 0x88) = corner;
    GRef<u32>(t + 0x18) = (static_cast<u32>(static_cast<s32>(u) + 0x100) & 0xFFFF) |
                          static_cast<u32>(static_cast<s32>(v) + 0x100) << 16;
    GRef<u32>(t + 0x48) = (sb & 0xFFFF) | tb << 16;
    GRef<u32>(t + 0x60) = (sc & 0xFFFF) | tc << 16;
    GRef<u32>(t + 0x78) = (sd & 0xFFFF) | td << 16;
    GRef<u32>(t + 0x10) = rgba;
    GRef<u32>(t + 0x28) = corner;
    GRef<u32>(t + 0x40) = corner;
    GRef<u32>(t + 0x58) = corner;
    GRef<u32>(t + 0x70) = corner;
    GRef<u32>(t + 0x30) = uv_a;
    GRef<u32>(gb + 0x10) = t;
    for (u32 o = 0x14; o <= 0x8C; o += 0x18) GRef<u32>(t + o) = 0;
    GRef<u32>(t + 0x90) = uv_a;
    const s32 x = GRef<s32>(s), y = GRef<s32>(s + 4), z = GRef<s32>(s + 8);
    GRef<u64>(t + 0x20) = GifXyz(x, y, z);
    const s32 a = GRef<s16>(junk), b = GRef<s16>(junk + 2), c = GRef<s16>(junk + 4), d = GRef<s16>(junk + 6);
    GRef<u64>(t + 0x98) = GifXyz(x - a, y - b, z);
    GRef<u64>(t + 0x38) = GifXyz(x - a, y - b, z);
    GRef<u64>(t + 0x50) = GifXyz(x - c, y - d, z);
    GRef<u64>(t + 0x68) = GifXyz(x + a, y + b, z);
    GRef<u64>(t + 0x80) = GifXyz(x + c, y + d, z);
}

