    const u32 p = BeginPacket();
    GRef<u32>(gb) = p;
    GRef<u32>(gb + 4) = 0;
    GRef<u32>(gb + 8) = 1;
    GRef<u32>(gb + 0xC) = p;
    GRef<u32>(gb + 0x10) = 0;
    GRef<u32>(gb + 0x14) = 0;
    GifOpenAd(gb);
    GRef<u64>(p + 0x28) = 0x3F;  // TEXFLUSH (data word not written)
    GRef<u32>(gb + 4) = 2;
    GRef<u32>(gb + 8) = 3;
    GRef<u32>(gb + 0x14) = 1;
    GifAd(gb, 0x8000000048ull, 0x42);
    CopyQ(pos, rec + 0xD0);
    NormRsqrt(dir, rec + 0xE0);
    {
        const f32 k = F(0x0040FDC0);
        for (u32 c = 0; c < 12; c += 4) GRef<f32>(pos + c) = vu0::Add(F(pos + c), vu0::Mul(F(dir + c), k));
    }
    const u32 eff_cam = W(0x004106B4) + 0x624E0;
    const u32 tbl = W(0x002B8558);
