            GRef<u32>(t + 0x88) = rim;
            GRef<u32>(t + 0x18) = 0x01000B00;
            GRef<u32>(t + 0x48) = uv(4);
            GRef<u32>(t + 0x60) = uv(0xC);
            GRef<u32>(t + 0x78) = uv(8);
            GRef<u32>(t + 0x28) = rim;
            GRef<u32>(t + 0x40) = rim;
            GRef<u32>(t + 0x58) = rim;
            GRef<u32>(t + 0x70) = rim;
            GRef<u32>(t + 0x30) = uv(0);
            GRef<u32>(t + 0x10) = col;
            for (u32 v = 0; v < 6; ++v) GRef<u32>(t + 0x14 + v * 0x18) = 0;
            GRef<u32>(t + 0x90) = uv(0);
