        const s32 hy = fpu::FloatToInt(size * F(cam + 0x184));
        GifOpenAd(gb);
        GifAd(gb, 0x156, 0);
        const u32 t = GifBeginTag(gb, 0x5400000000008001ull, 4);
        GRef<u32>(t + 0x18) = 0x80008;
        GRef<u32>(t + 0x10) = rgba;
        GRef<u32>(t + 0x28) = 0x1F801F8;
        const s32 x = GRef<s32>(scr), y = GRef<s32>(scr + 4), z = GRef<s32>(scr + 8);
        GRef<u64>(t + 0x20) = GifXyz(x - hx, y - hy, z);
        GRef<u64>(t + 0x30) = GifXyz(x + hx, y + hy, z);
        GRef<u64>(t + 8) = 0x53531;
