// EE: 0x001DEB70
// Rocket smoke trail of a rocket-trail record while it fades (rec+0xF0 < rec+0xF8): along the
// ring of 12 points at rec+0 (head +0xC4, tail +0xC8) each segment end gets a jittered sprite
// quad (PRIM 0x15C strips, TEX0 0x2005400621312600, UV cell (rec+0xFC + i) & 3 of four 64-texel
// cells) linking it to the previous end: the new end is the next point plus a random offset in
// +-2.5 (effect LCG 0x00410BB0), both ends projected with the clip test of the effect camera.
// Alpha = table 0x002B8558 word 0x24 alpha x remaining life, x (distance from the tail)^2 / 144;
// widths cam+0x168 x 128 / depth. A zero-length segment is a square of the larger width, one
// shorter than that width a square turned along it, longer ones a quad with each end's own width.
// Bucket 0x3FE.
// fpucheck: verified 13
void func_001DEB70(u32 rec, u32 cam, u32 list) {
    const s32 life = GRef<s32>(rec + 0xF8);
    if (!(GRef<s32>(rec + 0xF0) < life)) return;
    if ((GRef<s32>(rec + 0xC8) - GRef<s32>(rec + 0xC4) + 12) % 12 < 2) return;
    const u32 tbl = W(0x002B8558);
    const u32 tcol = W(tbl + 0x24);
    const u32 alpha = static_cast<u32>((tcol >> 24) * static_cast<u32>(life - GRef<s32>(rec + 0xF0))) /
                      static_cast<u32>(life);
    const u32 p = BeginPacket();
    guest::GuestFrame fr(0xA0);
    const u32 gb = fr.Address(0), A = fr.Address(0x20), B = fr.Address(0x30), P = fr.Address(0x40),
              D = fr.Address(0x50), s0 = fr.Address(0x60), R = fr.Address(0x70), s1 = fr.Address(0x80);
    GRef<u32>(gb) = p;
    GRef<u32>(gb + 4) = 0;
    GRef<u32>(gb + 8) = 1;
    GRef<u32>(gb + 0xC) = p;
    GRef<u32>(gb + 0x10) = 0;
    GRef<u32>(gb + 0x14) = 0;
    GifOpenAd(gb);
    GRef<u64>(p + 0x28) = 0x3F;  // TEXFLUSH (data word not written)
    GRef<u32>(gb + 4) = 2;
    GRef<u32>(gb + 8) = 3;
    GRef<u32>(gb + 0x14) = 1;
    GifAd(gb, 0x2005400621312600ull, 6);
    GifAd(gb, 0x8000000044ull, 0x42);
    const auto rand_unit = []() {
        const u32 u1 = W(0x00410BB0) * 0x10DCDu + 1u;
        const u32 u2 = u1 * 0x10DCDu + 1u;
        GRef<u32>(0x00410BB0) = u2;
        return fpu::UnsignedToFloat((u1 & 0xFFFF0000u) | (u2 >> 16)) * 2.3283064e-10f;
    };
    const u32 base = tcol & 0xFFFFFFu;
    for (s32 i = 1; i < (GRef<s32>(rec + 0xC8) - GRef<s32>(rec + 0xC4) + 12) % 12; ++i) {
        const s32 head = GRef<s32>(rec + 0xC4);
        CopyQ(A, rec + static_cast<u32>((head + i + 0xB) % 12) * 16);
        CopyQ(B, rec + static_cast<u32>((GRef<s32>(rec + 0xC4) + i + 0xC) % 12) * 16);
        const s32 cnt = (GRef<s32>(rec + 0xC8) - GRef<s32>(rec + 0xC4) + 12) % 12;
        const s32 k1 = cnt - i, k0 = cnt + 1 - i;
        const s32 a_far = static_cast<s32>(alpha * static_cast<u32>(k1 * k1)) / 0x90;
        const s32 a_near = static_cast<s32>(alpha * static_cast<u32>(k0 * k0)) / 0x90;
        CopyQ(P, A);
        sceVu0SubVector(D, B, A);
        for (u32 c = 0; c < 12; c += 4) GRef<f32>(D + c) = vu0::Mul(F(D + c), 1.0f);
        u32 clip0 = ClipProject(s0, W(0x004106B4) + 0x624E0, cam + 0xE0, P);
        for (s32 j = 0; j <= 0; ++j) {
            for (u32 c = 0; c < 12; c += 4) GRef<f32>(P + c) = vu0::Add(F(P + c), F(D + c));
            GRef<f32>(R) = fpu::Sub(rand_unit(), 0.5f) * 5.0f;
            GRef<f32>(R + 4) = fpu::Sub(rand_unit(), 0.5f) * 5.0f;
            const f32 rz = rand_unit();
            GRef<f32>(R + 0xC) = 1.0f;
            GRef<f32>(R + 8) = fpu::Sub(rz, 0.5f) * 5.0f;
            for (u32 c = 0; c < 12; c += 4) GRef<f32>(R + c) = vu0::Add(F(R + c), F(P + c));
            const u32 clip1 = ClipProject(s1, W(0x004106B4) + 0x624E0, cam + 0xE0, R);
            if (clip0 == 0 && clip1 == 0) {
                const f32 k = F(cam + 0x168) * 128.0f;
                const f32 size1 = k / fpu::IntToFloat(GRef<s32>(s1 + 0xC));
                const s32 al1 = a_near + (a_far - a_near) * (j + 1);
                const f32 size0 = k / fpu::IntToFloat(GRef<s32>(s0 + 0xC));
                const s32 al0 = a_near + (a_far - a_near) * j;
                const u32 c1 = base | (static_cast<u32>(al1) << 24);
                const u32 c0 = base | (static_cast<u32>(al0) << 24);
                if (!(al0 < 4 && al1 < 4)) {
                    const f32 dx = fpu::IntToFloat(GRef<s32>(s1) - GRef<s32>(s0));
                    const f32 dy = fpu::IntToFloat(GRef<s32>(s1 + 4) - GRef<s32>(s0 + 4));
                    const f32 len = fpu::Sqrt(fpu::MulAdd(dx * dx, dy, dy));
                    const f32 w = size0 < size1 ? size1 : size0;
                    const f32 ang = ee::atan2f(dy, dx);
                    const f32 sn = ee::sinf(ang), cs = ee::cosf(ang);
                    GifOpenAd(gb);
                    GifAd(gb, 0x15C, 0);
                    const u32 t = GifBeginTag(gb, 0x3400000000008004ull, 7);
                    GRef<u32>(t + 0x10) = c0;
                    GRef<u32>(t + 0x28) = c0;
                    const u32 cell = ((W(rec + 0xFC) + static_cast<u32>(i) + static_cast<u32>(j)) & 3) << 9;
                    GRef<u64>(t + 8) = 0x531;
                    GRef<u32>(t + 0x18) = (cell | 8) | 0x80000;
                    GRef<u32>(t + 0x30) = (cell | 0x1F8) | 0x80000;
                    GRef<u32>(t + 0x48) = (cell | 8) | 0x1F80000;
                    GRef<u32>(t + 0x60) = (cell | 0x1F8) | 0x1F80000;
                    const f32 sx = F(cam + 0x180), sy = F(cam + 0x184);
                    const s32 x0 = GRef<s32>(s0), y0 = GRef<s32>(s0 + 4), z0 = GRef<s32>(s0 + 8);
                    if (len == 0.0f) {
                        GRef<u32>(t + 0x58) = c0;
                        GRef<u32>(t + 0x40) = c0;
                        const s32 hy = fpu::FloatToInt(w * sy), hx = fpu::FloatToInt(w * sx);
                        GRef<u64>(t + 0x20) = GifXyz(x0 - hx, y0 - hy, z0);
                        GRef<u64>(t + 0x68) = GifXyz(x0 + hx, y0 + hy, z0);
                        GRef<u64>(t + 0x38) = GifXyz(x0 + hx, y0 - hy, z0);
                        GRef<u64>(t + 0x50) = GifXyz(x0 - hx, y0 + hy, z0);
                    } else if (len < w) {
                        const f32 smc = fpu::Sub(sn, cs), spc = fpu::Add(sn, cs), cms = fpu::Sub(cs, sn);
                        GRef<u32>(t + 0x58) = c0;
                        GRef<u32>(t + 0x40) = c0;
                        const s32 ay = fpu::FloatToInt(spc * w * sy), by = fpu::FloatToInt(smc * w * sy);
                        const s32 ax = fpu::FloatToInt(cms * w * sx), bx = fpu::FloatToInt(spc * w * sx);
                        GRef<u64>(t + 0x20) = GifXyz(x0 - ax, y0 - ay, z0);
                        GRef<u64>(t + 0x68) = GifXyz(x0 + ax, y0 + ay, z0);
                        GRef<u64>(t + 0x38) = GifXyz(x0 - bx, y0 - by, z0);
                        GRef<u64>(t + 0x50) = GifXyz(x0 + bx, y0 + by, z0);
                    } else {
                        const f32 smc = fpu::Sub(sn, cs), spc = fpu::Add(sn, cs), cms = fpu::Sub(cs, sn);
                        GRef<u32>(t + 0x58) = c1;
                        GRef<u32>(t + 0x40) = c1;
                        const s32 x1 = GRef<s32>(s1), y1 = GRef<s32>(s1 + 4), z1 = GRef<s32>(s1 + 8);
                        const s32 ay0 = fpu::FloatToInt(spc * size0 * sy), by0 = fpu::FloatToInt(smc * size0 * sy);
                        const s32 ay1 = fpu::FloatToInt(spc * size1 * sy), by1 = fpu::FloatToInt(smc * size1 * sy);
                        const s32 ax0 = fpu::FloatToInt(cms * size0 * sx), bx0 = fpu::FloatToInt(spc * size0 * sx);
                        const s32 ax1 = fpu::FloatToInt(cms * size1 * sx), bx1 = fpu::FloatToInt(spc * size1 * sx);
                        GRef<u64>(t + 0x20) = GifXyz(x0 - ax0, y0 - ay0, z0);
                        GRef<u64>(t + 0x68) = GifXyz(x1 + ax1, y1 + ay1, z1);
                        GRef<u64>(t + 0x38) = GifXyz(x0 - bx0, y0 - by0, z0);
                        GRef<u64>(t + 0x50) = GifXyz(x1 + bx1, y1 + by1, z1);
                    }
                }
            }
            CopyQ(s0, s1);
            clip0 = clip1;
        }
    }
    if (W(gb + 0x10) != 0) {
        GRef<u64>(W(gb + 0x10)) = GRef<u64>(gb + 0x18) | W(gb + 0x14) | 0x8000u;
        GRef<u32>(gb + 0x10) = 0;
    }
    GRef<u32>(p + 8) = 0;
    GRef<u64>(p) = static_cast<u64>(W(gb + 4) | 0x10000000u);
    GRef<u32>(p + 0xC) = (W(gb + 8) - 1) | 0x50000000u;
    EndPacket(list, 0x3FE, p + W(gb + 8) * 16);
}

// EE: 0x001DFA60
// Shell-trail record (ring of 3 points at rec+0, head +0x34, tail +0x38) as up to three glow
// sprites (PRIM 0x156, TEX0 0x2005400621312600, ALPHA_1 0x8000000048, colour table 0x002B8558
// word 0x2C), sized cam+0x168 x 192 / depth, projected with the scratchpad clip test set up by
// 0x001DF9D8: the newest point at alpha a (128, faded between the depths at 0x70000080 / +0x84 and
// below depth 0x100; nothing drawn when the point is clipped or a < 4), then with two or more
// points the midpoint of the newest two at 2a / 3 and the previous point at a / 3 (each only
// when >= 4). Bucket from the newest point's depth.
