    const u32 ring = rec + 0x10;
    const auto node = [ring](s32 k) {
        const u16 h = GRef<u16>(ring + static_cast<u32>(k % 0x6A) * 2);
        return W(0x004106B4) + 0x2010 + (h < 0x1000 ? static_cast<u32>(h) << 5 : 0x1FFE0u);
    };
    const auto mul = [](s32 a, s32 b) { return static_cast<s32>(static_cast<u32>(a) * static_cast<u32>(b)); };
    const s32 head = GRef<s32>(rec + 0xE8);
    const auto count = [rec, head]() { return (GRef<s32>(rec + 0xEC) - head + 0x6A) % 0x6A; };
    {
        guest::GuestFrame fr(0x10);
        const u32 d = fr.Address(0);
        const u32 eff = W(0x004106B4);
        sceVu0SubVector(d, eff + 0x62560, node(head + (count() + 0x69)));
        func_00210FB8(1.0f, W(0x004106B4) + 0x624A0 + static_cast<u32>(GRef<u8>(eff + 0x62592)) * 0x20, d,
                      W(W(0x002B8534) + 8));
    }
    const s32 half = GRef<s32>(rec + 0xF8) / 2;
    const s32 fade_n = half < 0x40 ? half : 0x40;
