    const u32 eff = W(0x004106B4);
    const s32 kind = GRef<s16>(rec + 0xFC);
    const s32 near_z = fpu::FloatToInt(F(eff + 0x62498));
    const s32 base = GRef<s32>(0x004059A0 + static_cast<u32>(kind) * 4);
    const s32 far_z = fpu::FloatToInt(F(eff + 0x62494));
