        GRef<f32>(pb + 0xC) = 1.0f;
        ProjectI4(0x70000140, proj, pa, true);
        ProjectI4(0x70000150, proj, pb, true);
        const s32 ex = GRef<s32>(0x70000150) - GRef<s32>(seg + 0x10);
        const s32 ey = GRef<s32>(0x70000154) - GRef<s32>(seg + 0x14);
        GRef<f32>(0x70000170) = fpu::IntToFloat(GRef<s32>(0x70000150) - GRef<s32>(0x70000140));
        GRef<f32>(0x70000174) = fpu::IntToFloat(GRef<s32>(0x70000154) - GRef<s32>(0x70000144));
        const s32 d2 = mul(ex, ex) + mul(ey, ey);
