    ab = depth_fade(ab, zb);
    GRef<s16>(seg + 0x22) = static_cast<s16>(aa);
    GRef<s16>(seg + 0x62) = static_cast<s16>(ab);
    GRef<s16>(seg + 0x20) = static_cast<s16>(wa);
    GRef<s16>(seg + 0x60) = static_cast<s16>(wb);
    if (wa < 0x20 && wb < 0x20) func_001DBE70(rec, cam, list, seg);
    else func_002019D0(rec, cam, list, seg);
