        const u32 r1 = W(gen) * 0x10DCDu + 1u;
        const u32 r2 = r1 * 0x10DCDu + 1u;
        GRef<u32>(gen) = r2;
        return fpu::UnsignedToFloat((r1 & 0xFFFF0000u) | (r2 >> 16));
