    GRef<f32>(pos + 8) = fpu::Add(F(pos + 8), fpu::Sub(draw() * unit, 0.5f) * spread);
    GRef<f32>(pos + 4) = fpu::Sub(func_0013E338(W(0x00410694), pos), fpu::Add(scale, scale));
    func_001E24C8(cam, list, gen, pos, ph, scale, tbl);
