    sceVu0ApplyMatrix(b, m, b);
    sceVu0ApplyMatrix(c, m, c);
    sceVu0CopyVector(pos, obj);
    sceVu0AddVector(a, a, pos);
    sceVu0AddVector(b, b, pos);
    sceVu0AddVector(c, c, pos);
    sceVu0SubVector(e2, b, a);
    sceVu0SubVector(e1, pos, a);
    sceVu0OuterProduct(nrm, e2, e1);
    sceVu0Normalize(nrm, nrm);
    for (u32 k = 0; k < 4; ++k) sceVu0SubVector(view + k * 16, cam, pos + k * 16);
    for (u32 k = 0; k < 4; ++k) sceVu0Normalize(view + k * 16, view + k * 16);
    f32 dot[4];
    for (u32 k = 0; k < 4; ++k) dot[k] = sceVu0InnerProduct(view + k * 16, nrm);
    for (u32 k = 0; k < 4; ++k) sceVu0ScaleVector(proj + k * 16, nrm, dot[k]);
    for (u32 k = 0; k < 4; ++k) sceVu0SubVector(refl + k * 16, proj + k * 16, view + k * 16);
    for (u32 k = 0; k < 4; ++k) sceVu0AddVector(view + k * 16, refl + k * 16, proj + k * 16);
    for (u32 k = 0; k < 4; ++k) {
        const u32 v = view + k * 16, t = uv + k * 16;
        GRef<f32>(t) = fpu::Add(F(v), 1.0f) * 0.5f;
        GRef<f32>(t + 4) = fpu::Add(-F(v + 8), 1.0f) * 0.5f;
        GRef<f32>(t + 8) = 1.0f;
        GRef<u32>(t + 0xC) = 0;
    }
