    for (u32 k = 0; k < 4; ++k) {
        const u32 t = uv + k * 16;
        if (F(t) < lo) GRef<f32>(t) = lo;
        if (F(t + 4) < lo) GRef<f32>(t + 4) = lo;
        if (hi < F(t)) GRef<f32>(t) = hi;
        if (hi < F(t + 4)) GRef<f32>(t + 4) = hi;
    }
