    for (u32 i = 0; i < 4; ++i) GRef<f32>(col + i * 4) = fpu::UnsignedToFloat((rgba >> (8 * i)) & 0xFF);
    for (u32 k = 1; k < 4; ++k) sceVu0CopyVector(col + k * 16, col);
    const u32 terrain = W(0x00410694);
    GRef<f32>(fog + 0xC) = 128.0f;
    const f32 start = F(terrain + 0xA4);
    const f32 span = fpu::Sub(start, F(terrain + 0xA8));
    GRef<f32>(fog + 8) = -1.0f;
    GRef<f32>(fog) = start;
    GRef<f32>(fog + 4) = 128.0f / span;
    u32 q = WriteTex0Tex1(W(W(0x00410688) + 0x40), BeginPacket());
    GRef<u32>(q + 4) = 0;
    GRef<u32>(q) = 0x10000003;
    GRef<u32>(q + 8) = 0;
    GRef<u32>(q + 0xC) = 0x50000003;
    GRef<u32>(q + 0x10) = 0x8002;
    GRef<u32>(q + 0x18) = 0xE;
    GRef<u32>(q + 0x14) = 0x10000000;
