    GRef<f32>(S + 0x4E4) = F(pal + 0x50) * F(S + 0x630);
    GRef<f32>(S + 0x4E8) = F(pal + 0x5C) * F(S + 0x630);
    GRef<f32>(S + 0x660) = fpu::IntToFloat(GRef<u8>(obj + 0x3C)) * F(0x0040F4B8) * 0.03125f;
    const u32 sum = W(eff + 0x6249C) + static_cast<u32>(fpu::FloatToInt(F(obj + 0x38)));
