    GRef<f32>(S + 0x620) = fpu::IntToFloat(GRef<u8>(obj + 0x33));
    GRef<f32>(S + 0x62C) = F(obj + 0x34) * 60.0f;
    GRef<s32>(S + 0x628) = fpu::FloatToInt(F(S + 0x62C));
    GRef<f32>(S + 0x630) = 60.0f / F(obj + 0x34);
