    GRef<u32>(S + 0x4B0) = W(obj);
    GRef<u32>(S + 0x4B4) = W(obj + 4);
    GRef<s32>(S + 0x61C) = fpu::FloatToInt(F(obj + 0x38) * 60.0f);
    GRef<f32>(S + 0x4BC) = 1.0f;
    GRef<u32>(S + 0x4B8) = W(obj + 8);
    for (u32 i = 0; i < 16; i += 4) GRef<u32>(S + 0x6B0 + i) = W(ctab + 0x19C + i);
