    GRef<u32>(hp + 0x1C) = 0;
    GRef<u64>(hp + 0x20) = 0x2005408621312700ull;
    GRef<u32>(hp + 0x28) = 6;
    GRef<u32>(hp + 0x2C) = 0;
    GRef<u32>(hp + 0x30) = 1;
    GRef<u32>(hp + 0x34) = 0x10000000;
    GRef<u32>(hp + 0x38) = 0xE;
    GRef<u32>(hp + 0x3C) = 0;
    GRef<u32>(hp + 0x40) = 0x44;
    GRef<u32>(hp + 0x44) = 0x80;
    GRef<u32>(hp + 0x48) = 0x42;
    GRef<u32>(hp + 0x4C) = 0;
    GRef<u32>(S + 0x570) = hp + 0x50;
    const u32 noise = 0x002B91C0;
    const auto T = [noise](s32 i) { return noise + static_cast<u32>(i & 0x7F) * 16; };
    const f32 k0 = F(0x0040F570), k1 = F(0x0040F574), k2 = F(0x0040F578), k3 = F(0x0040F57C);
    // Corner texture table filled per variant (dc + j) mod 4 (not read by the packet).
    const f32 tab_s[4][4] = {{k0, k2, k2, k0}, {k0, k0, k2, k2}, {k2, k0, k0, k2}, {k2, k2, k0, k0}};
    const f32 tab_t[4][4] = {{k1, k1, k3, k3}, {k3, k1, k1, k3}, {k3, k3, k1, k1}, {k1, k3, k3, k1}};
    const f32 st[6][2] = {{0.125f, 0.375f}, {0.0f, 0.25f}, {0.25f, 0.25f}, {0.25f, 0.5f}, {0.0f, 0.5f}, {0.0f, 0.25f}};
