                            fpu::Add(F(T(u) + 8) * 0.5f, 1.0f);
            const f32 kx = fpu::Add(fpu::Add(wob, 4.0f), a * F(0x0040F594) * 16.0f);
            const f32 ky = fpu::Add(a * F(0x0040F598) * 16.0f, 4.0f);
