            GRef<f32>(S + 0x564) = fpu::Add(F(S + 0x564), F(S + 0x4E4) * a) * gy;
            GRef<f32>(S + 0x568) = fpu::Add(F(S + 0x568), F(S + 0x4E8) * a) * gx;
            for (u32 c = 0; c < 12; c += 4) GRef<f32>(S + 0x4A0 + c) = vu0::Add(F(S + 0x4A0 + c), F(S + 0x560 + c));
            ProjectI4(S + 0x410, cam + 0xE0, S + 0x4A0, true);
            const s32 d0 = GRef<s32>(S + 0x41C);
            const s32 x = GRef<s32>(S + 0x410), y = GRef<s32>(S + 0x414);
            if (d0 < 0x10 || GRef<s32>(S + 0x5EC) < x || x < GRef<s32>(S + 0x5F0) || GRef<s32>(S + 0x5F4) < y ||
                y < GRef<s32>(S + 0x5F8))
                continue;
