            GRef<u32>(p + 8) = 0xE;
            GRef<u32>(p + 0xC) = 0;
            GRef<u32>(p + 0x10) = 0x5D;  // PRIM; the upper data word is left as it is
            GRef<u32>(p + 0x18) = 0;
            GRef<u32>(p + 0x1C) = 0;
