    GRef<s32>(S + 0x57C) = fpu::FloatToInt(fpu::Sub(F(eff + 0x62494), F(eff + 0x62498)) / F(0x0040F5AC));
    for (u32 i = 0; i < 16; i += 4) GRef<u32>(S + 0x5EC + i) = W(ctab + 4 + i);
    for (u32 c = 0; c < 3; ++c) GRef<u32>(S + 0x580 + c * 4) = GRef<u8>(obj + 0x30 + c);
    GRef<f32>(S + 0x620) = fpu::IntToFloat(GRef<u8>(obj + 0x33)) * F(0x0040F5AC);
    if (255.0f < F(S + 0x620)) GRef<f32>(S + 0x620) = 255.0f;
    const u32 pal = W(0x002B8550), wind = W(0x002B855C);
    GRef<f32>(S + 0x62C) = F(obj + 0x34) * 60.0f;
    const s32 period_i = fpu::FloatToInt(F(S + 0x62C));
    for (u32 c = 0; c < 3; ++c) {
        GRef<u32>(S + 0x58C + c * 4) = GRef<u8>(pal + c);
        GRef<s32>(S + 0x598 + c * 4) = (GRef<s32>(S + 0x580 + c * 4) + GRef<s32>(S + 0x58C + c * 4)) / 2;
    }
