    GRef<s32>(S + 0x61C) = fpu::FloatToInt(F(obj + 0x38) * 60.0f);
    for (u32 c = 0; c < 12; c += 4) GRef<f32>(S + 0x4E0 + c) = F(wind + c) * F(0x0040F5B0) * F(S + 0x630);
