    GRef<u32>(hp + 0x48) = 6;
    GRef<u32>(hp + 0x4C) = 0;
    GRef<u32>(hp + 0x50) = 1;
    GRef<u32>(hp + 0x54) = 0x10000000;
    GRef<u32>(hp + 0x58) = 0xE;
    GRef<u32>(hp + 0x5C) = 0;
