    GRef<f32>(S + 0x63C) = fpu::UnsignedToFloat(sum % static_cast<u32>(GRef<s32>(S + 0x628)));
    GRef<u32>(S + 0x4B0) = W(obj);
    GRef<u32>(S + 0x4B4) = W(obj + 4);
    GRef<s32>(S + 0x61C) = fpu::FloatToInt(F(obj + 0x38) * 60.0f);
    GRef<u32>(S + 0x4B8) = W(obj + 8);
    GRef<f32>(S + 0x4BC) = 1.0f;
    for (u32 i = 0; i < 16; i += 4) GRef<u32>(S + 0x6B0 + i) = W(ctab + 0x19C + i);
    GRef<u32>(S + 0x6C0) = W(ctab + 0x214);
    GRef<u32>(S + 0x6C4) = W(ctab + 0x218);
    const u32 hp = AllocBucketPacket(list, GRef<s32>(S + 0x5FC), 5, 0, 0x50000005);
    GRef<u32>(S + 0x570) = hp;
    const f32 ta = F(0x0040F538), tb = F(0x0040F53C);
    GRef<u32>(hp) = 2;
    GRef<u32>(hp + 4) = 0x10000000;
    GRef<u32>(hp + 8) = 0xE;
