            GRef<f32>(S + 0x654) = size;
            GRef<s32>(S + 0x41C) = d1;
            GRef<s32>(S + 0x60C) = fpu::FloatToInt(F(S + 0x6B0 + par * 8) * size / depth);
            GRef<s32>(S + 0x610) = fpu::FloatToInt(F(S + 0x6B0 + (par * 2 + 1) * 4) * size / depth);
